import { test } from "node:test";
import assert from "node:assert/strict";
import { escapeHtml, safeUrl } from "../src/reviews/escape.ts";
import { renderReviewCard, type Review } from "../src/reviews/card.ts";
import { buildWeeklyDigest } from "../src/reviews/digest.ts";

const review = (over: Partial<Review> = {}): Review => ({
    id: "r1",
    authorName: "Priya",
    rating: 4,
    body: "Great dumplings.\n\nSlow service on Friday.",
    postedAt: "2026-11-14T19:30:00Z",
    ...over,
});

test("a review card shows the author, stars, date and paragraphs", () => {
    const html = renderReviewCard(review());
    assert.ok(html.includes(`<h3 title="Review by Priya">Priya <span class="stars">★★★★☆</span></h3>`));
    assert.ok(html.includes(`<time datetime="2026-11-14T19:30:00Z">2026-11-14</time>`));
    assert.ok(html.includes("<p>Great dumplings.</p><p>Slow service on Friday.</p>"));
});

test("markup typed into a review is shown as text, every time it appears", () => {
    const html = renderReviewCard(review({ body: "The <b>best</b> noodles, <i>truly</i>." }));
    console.log("rendered body:", html.match(/<p>.*<\/p>/)?.[0]);
    assert.ok(html.includes("<p>The &lt;b&gt;best&lt;/b&gt; noodles, &lt;i&gt;truly&lt;/i&gt;.</p>"));
});

test("an author name can't close the title attribute and add its own", () => {
    const html = renderReviewCard(review({ authorName: `Sam" data-x="1" onclick="steal()` }));
    const h3 = html.match(/<h3[^>]*>/)?.[0] ?? "";
    // the only raw quotes in the tag should be the two around the title value
    assert.equal(h3.split('"').length - 1, 2, h3);
    assert.ok(h3.startsWith(`<h3 title="Review by Sam&quot; data-x=&quot;1&quot;`));
});

test("every ampersand is escaped exactly once", () => {
    assert.equal(escapeHtml("Fish & Chips & Peas"), "Fish &amp; Chips &amp; Peas");
    assert.equal(escapeHtml("&lt;"), "&amp;lt;");
    assert.equal(escapeHtml(`it's "fine"`), "it&#39;s &quot;fine&quot;");
});

test("only http(s) photo links are kept", () => {
    assert.equal(safeUrl("javascript:alert(document.cookie)"), null);
    assert.equal(safeUrl("data:text/html,hi"), null);
    assert.equal(safeUrl("not a url"), null);
    assert.equal(safeUrl(" https://img.example.com/a.jpg "), "https://img.example.com/a.jpg");
    assert.ok(!renderReviewCard(review({ photoUrl: "javascript:void(0)" })).includes("<a "));
});

test("the digest lists the newest reviews first, up to the limit", () => {
    const reviews = ["2026-11-10", "2026-11-15", "2026-11-12", "2026-11-13"].map((d, i) => review({ id: `r${i}`, postedAt: `${d}T12:00:00Z` }));
    const { html } = buildWeeklyDigest({ id: "x", name: "Lotus" }, reviews, 3);
    const ids = [...html.matchAll(/data-id="(\w+)"/g)].map((m) => m[1]);
    assert.deepEqual(ids, ["r1", "r3", "r2"]);
    assert.ok(html.includes("4 new reviews, averaging 4.0 stars."));
});

test("low ratings without a reply are called out, and owner replies render under the review", () => {
    const reviews = [
        review({ id: "a", rating: 1 }),
        review({ id: "b", rating: 2, ownerReply: { body: "Sorry, we'll do better.", repliedAt: "2026-11-15T09:00:00Z" } }),
    ];
    const { html } = buildWeeklyDigest({ id: "x", name: "Lotus" }, reviews);
    assert.ok(html.includes(`<p class="attention">1 low rating is waiting for a reply.</p>`));
    assert.ok(html.includes("<strong>Owner replied on 2026-11-15</strong><p>Sorry, we&#39;ll do better.</p>"));
});

test("a restaurant name with markup is escaped in the digest heading", () => {
    const { subject, html } = buildWeeklyDigest({ id: "x", name: "<i>Joe's</i> <b>Diner</b>" }, []);
    assert.equal(subject, "This week at <i>Joe's</i> <b>Diner</b>");
    assert.ok(html.includes("<h1>This week at &lt;i&gt;Joe&#39;s&lt;/i&gt; &lt;b&gt;Diner&lt;/b&gt;</h1>"));
});
